function makeId(prefix: string) {
  return `${prefix}_${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

function escapeHtml(value: string) {
  return value
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function plainTextToHtml(value: string) {
  const blocks = value
    .split(/\n\s*\n/g)
    .map((block) => block.trim())
    .filter(Boolean);

  if (!blocks.length) return "<p><br></p>";

  return blocks
    .map((block) => {
      const lines = block.split(/\n/g).map((line) => line.trim()).filter(Boolean);
      const singleLine = lines.length === 1 ? lines[0] : "";

      if (/^#{1,2}\s+/.test(singleLine)) {
        const level = singleLine.startsWith("##") ? "h2" : "h1";
        return `<${level}>${escapeHtml(singleLine.replace(/^#{1,2}\s+/, ""))}</${level}>`;
      }

      if (lines.length > 1 && lines.every((line) => /^[-*Ã¢â‚¬Â¢]\s+/.test(line))) {
        return `<ul>${lines
          .map((line) => `<li>${escapeHtml(line.replace(/^[-*Ã¢â‚¬Â¢]\s+/, ""))}</li>`)
          .join("")}</ul>`;
      }

      if (lines.length > 1 && lines.every((line) => /^\d+[.)]\s+/.test(line))) {
        return `<ol>${lines
          .map((line) => `<li>${escapeHtml(line.replace(/^\d+[.)]\s+/, ""))}</li>`)
          .join("")}</ol>`;
      }

      const wordCount = countWords(singleLine);
      const looksLikeHeading =
        singleLine &&
        wordCount > 0 &&
        wordCount <= 12 &&
        singleLine.length <= 90 &&
        !/[.!?:;]$/.test(singleLine);

      if (looksLikeHeading) {
        return `<h2>${escapeHtml(singleLine)}</h2>`;
      }

      return `<p>${escapeHtml(block).replace(/\n/g, "<br>") || "<br>"}</p>`;
    })
    .join("");
}

function extractByChars(text: string, maxChars: number): string[] {
  if (!text || maxChars <= 0) return [];

  const chunks: string[] = [];
  let cursor = 0;

  while (cursor < text.length) {
    let end = cursor + maxChars;

    if (end < text.length) {
      const nearestBreak = Math.max(
        text.lastIndexOf("\n\n", end),
        text.lastIndexOf(". ", end),
        text.lastIndexOf(" ", end)
      );

      if (nearestBreak > cursor) end = nearestBreak + 1;
    }

    const piece = text.slice(cursor, end).trim();
    if (piece) chunks.push(piece);

    cursor = end + 1;
  }

  return chunks;
}

function countWords(text: string) {
  return text.trim().split(/\s+/).filter(Boolean).length;
}

function splitFlatWords(text: string, minWords: number, maxWords: number): string[] {
  const words = text.trim().split(/\s+/).filter(Boolean);
  const safeMax = Math.max(1, maxWords || 180);
  const safeMin = Math.max(1, Math.min(minWords || 1, safeMax));
  const chunks: string[] = [];
  let cursor = 0;

  while (cursor < words.length) {
    let end = Math.min(cursor + safeMax, words.length);
    if (end < words.length) {
      const windowText = words.slice(cursor, end).join(" ");
      const lastSentenceBreak = Math.max(
        windowText.lastIndexOf(". "),
        windowText.lastIndexOf("! "),
        windowText.lastIndexOf("? "),
        windowText.lastIndexOf("Ã›â€ "),
        windowText.lastIndexOf("Ã˜Å’ ")
      );

      if (lastSentenceBreak > -1) {
        const beforeBreak = windowText.slice(0, lastSentenceBreak + 1);
        const breakWords = countWords(beforeBreak);
        if (breakWords >= safeMin) end = cursor + breakWords;
      }
    }

    const piece = words.slice(cursor, end).join(" ").trim();
    if (piece) chunks.push(piece);
    cursor = end;
  }

  return chunks;
}

function extractByWords(text: string, minWords: number, maxWords: number): string[] {
  const paragraphs = text
    .split(/\n\s*\n/g)
    .map((item) => item.trim())
    .filter(Boolean);

  if (paragraphs.length <= 1) return splitFlatWords(text, minWords, maxWords);

  const safeMax = Math.max(1, maxWords || 180);
  const safeMin = Math.max(1, Math.min(minWords || 1, safeMax));
  const chunks: string[] = [];
  let buffer = "";

  for (const paragraph of paragraphs) {
    const paragraphWords = countWords(paragraph);
    const bufferWords = countWords(buffer);
    const next = buffer ? `${buffer}\n\n${paragraph}` : paragraph;
    const nextWords = countWords(next);

    if (paragraphWords > safeMax) {
      if (buffer.trim()) {
        chunks.push(buffer.trim());
        buffer = "";
      }
      chunks.push(...splitFlatWords(paragraph, safeMin, safeMax));
    } else if (buffer && nextWords > safeMax && bufferWords >= safeMin) {
      chunks.push(buffer.trim());
      buffer = paragraph;
    } else {
      buffer = next;
    }
  }

  if (buffer.trim()) chunks.push(buffer.trim());

  return chunks;
}

function extractByParagraphs(text: string, maxChars: number): string[] {
  const paragraphs = text
    .split(/\n\s*\n/g)
    .map((item) => item.trim())
    .filter(Boolean);

  const chunks: string[] = [];
  let buffer = "";

  for (const paragraph of paragraphs) {
    const next = buffer ? `${buffer}\n\n${paragraph}` : paragraph;

    if (next.length > maxChars && buffer) {
      chunks.push(buffer.trim());
      buffer = paragraph;
    } else {
      buffer = next;
    }
  }

  if (buffer.trim()) chunks.push(buffer.trim());

  return chunks;
}

function extractParagraphsByWords(text: string, minWords: number, maxWords: number): string[] {
  const paragraphs = text
    .split(/\n\s*\n/g)
    .map((item) => item.trim())
    .filter(Boolean);
  const chunks: string[] = [];
  let buffer = "";

  for (const paragraph of paragraphs) {
    const next = buffer ? `${buffer}\n\n${paragraph}` : paragraph;
    if (countWords(next) > maxWords && countWords(buffer) >= minWords) {
      chunks.push(buffer.trim());
      buffer = paragraph;
    } else if (countWords(paragraph) > maxWords) {
      if (buffer.trim()) chunks.push(buffer.trim());
      chunks.push(...splitFlatWords(paragraph, minWords, maxWords));
      buffer = "";
    } else {
      buffer = next;
    }
  }

  if (buffer.trim()) chunks.push(buffer.trim());

  return chunks;
}

function extractByMarkers(text: string, startCode: string, endCode: string): string[] {
  if (!text || !startCode || !endCode) return [];

  const chunks: string[] = [];
  let searchFrom = 0;

  while (true) {
    const start = text.indexOf(startCode, searchFrom);
    if (start === -1) break;

    const end = text.indexOf(endCode, start + startCode.length);
    if (end === -1) break;

    const piece = text.slice(start + startCode.length, end).trim();
    if (piece) chunks.push(piece);

    searchFrom = end + endCode.length;
  }

  return chunks;
}

function formatNumber(value: number): string {
  if (value >= 1000000) return `${(value / 1000000).toFixed(1)}M`;
  if (value >= 1000) return `${(value / 1000).toFixed(1)}K`;
  return String(value);
}

function getPlatform(id: PlatformId): Platform | undefined {
  return PLATFORMS.find((item) => item.id === id);
}

function asRecord(value: unknown): Record<string, unknown> {
  return value && typeof value === "object" ? (value as Record<string, unknown>) : {};
}

function asArray(value: unknown): unknown[] {
  if (Array.isArray(value)) return value;
  const record = asRecord(value);
  const candidates = [
    record.items,
    record.chunks,
    record.articles,
    record.queue,
    record.history,
    record.results,
    asRecord(record.data).items,
    asRecord(record.data).chunks,
    asRecord(record.data).articles,
    asRecord(record.data).queue,
    asRecord(record.data).history,
    asRecord(record.data).results,
  ];
  return (candidates.find(Array.isArray) as unknown[]) || [];
}

function stringField(record: Record<string, unknown>, keys: string[], fallback = "") {
  for (const key of keys) {
    const value = record[key];
    if (typeof value === "string" && value.trim()) return value;
    if (typeof value === "number") return String(value);
  }
  return fallback;
}

function numberField(record: Record<string, unknown>, keys: string[], fallback = 0) {
  for (const key of keys) {
    const value = record[key];
    if (typeof value === "number") return value;
    if (typeof value === "string" && Number.isFinite(Number(value))) return Number(value);
  }
  return fallback;
}

