  function mapRemoteMediaAsset(
    remoteAsset: UnapiMediaAsset | undefined,
    postId: string,
    postCode: string,
    mediaType: MediaType,
    source: MediaSource,
    storedName: string,
    version: number
  ): MediaAsset {
    return {
      id: String(remoteAsset?.id || makeId("media")),
      postId: remoteAsset?.post_id || postId,
      postCode: remoteAsset?.post_code || postCode,
      type: remoteAsset?.type || mediaType,
      source: remoteAsset?.source || source,
      originalName: remoteAsset?.original_name || storedName,
      storedName: remoteAsset?.stored_name || storedName,
      url:
        remoteAsset?.url ||
        (mediaType === "image" ? createMediaSvgDataUrl(postCode, mediaType) : ""),
      mimeType: remoteAsset?.mime_type || (mediaType === "image" ? "image/svg+xml" : "video/mp4"),
      size: remoteAsset?.size,
      version: remoteAsset?.version || version,
      status: remoteAsset?.status || "ready",
      createdAt: remoteAsset?.created_at || new Date().toISOString(),
    };
  }

  async function createMediaByPlaceholder(draftId: string, mediaType: MediaType) {
    setShowSettingsModal(true);
    alert(
      lang === "en"
        ? "You are not connected to any AI agent yet. Please add a valid API key in Settings first."
        : "Anda belum terhubung ke AI agent manapun. Silakan tambahkan API key yang valid di menu Setting terlebih dahulu."
    );
  }

  async function importMediaForDraft(
    draftId: string,
    mediaType: MediaType,
    event: ChangeEvent<HTMLInputElement>
  ) {
    const file = event.target.files?.[0];
    if (!file) return;

    const isImage = mediaType === "image";
    const isVideo = mediaType === "video";

    if (isImage && !file.type.startsWith("image/")) {
      alert(lang === "en" ? "Please choose an image file." : "Silakan pilih file gambar.");
      return;
    }

    if (isVideo && !file.type.startsWith("video/")) {
      alert(lang === "en" ? "Please choose a video file." : "Silakan pilih file video.");
      return;
    }

    if (isVideo && file.size > MAX_VIDEO_UPLOAD_SIZE) {
      alert(
        lang === "en"
          ? "Video is too large. Please upload a video up to 90 MB so it stays safe for social posting."
          : "Ukuran video terlalu besar. Silakan upload video maksimal 90 MB agar aman untuk kebutuhan posting sosial."
      );
      event.target.value = "";
      return;
    }

    const postCode = getDraftPostCode(draftId);
    const version = getMediaVersion(draftId, "user", mediaType);
    const extension = normalizeExtension(file.name, mediaType);
    const storedName = buildMediaFileName(postCode, "user", mediaType, version, extension);
    const busyKey = `${draftId}_${mediaType}_user`;
    const localAsset: MediaAsset = {
      id: makeId("media_local"),
      postId: draftId,
      postCode,
      type: mediaType,
      source: "user",
      originalName: file.name,
      storedName,
      url: URL.createObjectURL(file),
      mimeType: file.type,
      size: file.size,
      version,
      status: "ready",
      createdAt: new Date().toISOString(),
    };

    setMediaAssets((prev) => [localAsset, ...prev]);
    setMediaNotNeededDraftIds((prev) => prev.filter((id) => id !== draftId));
    setApiNotice(
      mediaType === "image"
        ? lang === "en"
          ? "Image uploaded successfully."
          : "Gambar berhasil diupload."
        : lang === "en"
          ? "Video uploaded successfully."
          : "Video berhasil diupload."
    );

    if (!accessToken) {
      event.target.value = "";
      return;
    }

    setMediaBusy((prev) => ({ ...prev, [busyKey]: true }));
    try {
      const draft = drafts.find((item) => item.id === draftId);
      const response = await importMediaOnUnapi(accessToken, {
        app_code: APP_CODE,
        postId: draftId,
        postCode,
        mediaType,
        caption: draft?.caption,
        visualPrompt: draft?.visualPrompt,
        platforms: draft?.platforms,
        version,
        storedName,
        file,
      });

      const asset = mapRemoteMediaAsset(response.asset, draftId, postCode, mediaType, "user", storedName, version);
      setMediaAssets((prev) => prev.map((item) => (item.id === localAsset.id ? asset : item)));
    } catch (error) {
      setApiNotice(
        lang === "en"
          ? "The file is visible locally, but it could not be synced to UNAPI yet."
          : "File sudah tampil di lokal, tetapi belum berhasil disinkronkan ke UNAPI."
      );
    } finally {
      setMediaBusy((prev) => ({ ...prev, [busyKey]: false }));
    }

    event.target.value = "";
  }

  async function insertVideoLinkForDraft(draftId: string) {
    const rawUrl = window.prompt(
      lang === "en"
        ? "Paste a YouTube, Google Drive, or other video link."
        : "Paste link video YouTube, Google Drive, atau sumber video lain."
    );
    const cleanUrl = rawUrl?.trim();
    if (!cleanUrl) return;

    try {
      new URL(cleanUrl);
    } catch {
      alert(lang === "en" ? "Please insert a valid video URL." : "Silakan masukkan URL video yang valid.");
      return;
    }

    const postCode = getDraftPostCode(draftId);
    const version = getMediaVersion(draftId, "link", "video");
    const asset: MediaAsset = {
      id: makeId("media_link"),
      postId: draftId,
      postCode,
      type: "video",
      source: "link",
      originalName: cleanUrl,
      storedName: `linked-video-v${version}`,
      url: cleanUrl,
      mimeType: "text/uri-list",
      version,
      status: "ready",
      createdAt: new Date().toISOString(),
    };

    setMediaAssets((prev) => [asset, ...prev]);
    setMediaNotNeededDraftIds((prev) => prev.filter((id) => id !== draftId));
    setApiNotice(lang === "en" ? "Video link added." : "Link video berhasil ditambahkan.");

    if (!accessToken) return;

    const draft = drafts.find((item) => item.id === draftId);
    const busyKey = `${draftId}-link-video`;
    setMediaBusy((prev) => ({ ...prev, [busyKey]: true }));
    try {
      const response = await importMediaLinkOnUnapi(accessToken, {
        app_code: APP_CODE,
        postId: draftId,
        postCode,
        mediaType: "video",
        url: cleanUrl,
        name: asset.originalName,
        caption: draft?.caption,
        visualPrompt: draft?.visualPrompt,
        platforms: draft?.platforms,
        version,
        storedName: asset.storedName,
      });
      const remoteAsset = mapRemoteMediaAsset(response.asset, draftId, postCode, "video", "link", asset.storedName, version);
      setMediaAssets((prev) => prev.map((item) => (item.id === asset.id ? remoteAsset : item)));
      setApiNotice(lang === "en" ? "Video link synced to UNAPI." : "Link video berhasil disinkronkan ke UNAPI.");
    } catch (error) {
      setApiNotice(
        error instanceof Error
          ? error.message
          : lang === "en"
            ? "Video link is visible locally, but it could not be synced to UNAPI yet."
            : "Link video sudah tampil lokal, tetapi belum berhasil disinkronkan ke UNAPI."
      );
    } finally {
      setMediaBusy((prev) => ({ ...prev, [busyKey]: false }));
    }
  }

  function markNoMediaNeeded(draftId: string) {
    setMediaNotNeededDraftIds((prev) => (prev.includes(draftId) ? prev : [...prev, draftId]));
  }

  function scheduleSingleDraft(draftId: string) {
    const draft = drafts.find((item) => item.id === draftId);
    if (!draft) return;

    setDrafts((prev) =>
      prev.map((item) => (item.id === draftId ? { ...item, status: "approved" } : item))
    );

    setQueue((prev) => {
      if (prev.some((item) => item.draftId === draftId)) return prev;
      return [
        ...prev,
        {
          id: makeId("queue"),
          draftId,
          caption: draft.caption,
          platforms: draft.platforms,
          image: draft.image,
          publishMode: "scheduled",
          status: "ready",
        },
      ];
    });

    setStep("schedule");
  }
