  function createReadyPostDraft() {
    const cleanText = readyPostContent.trim();
    if (!cleanText) {
      alert(
        lang === "en"
          ? "Please insert your ready-to-post content first."
          : "Silakan masukkan konten siap posting terlebih dahulu."
      );
      return;
    }

    const draftId = makeId("ready_draft");
    const chunkId = makeId("ready_chunk");
    setChunks((prev) => [
      {
        id: chunkId,
        index: prev.length + 1,
        text: cleanText,
        charCount: cleanText.length,
      },
      ...prev,
    ]);
    setDrafts((prev) => [
      {
        id: draftId,
        chunkId,
        caption: cleanText,
        richHtml: plainTextToHtml(cleanText),
        platforms: [],
        status: "approved",
      },
      ...prev,
    ]);
    setReadyPostContent("");
    setApiNotice(
      lang === "en"
        ? "Ready content added to Media Studio."
        : "Konten siap posting ditambahkan ke Media Studio."
    );
  }

