  async function handleGoogleLogin() {
    setAuthBusy(true);
    try {
      const config = await getGoogleAuthConfig();
      await loadGoogleScript();

      const google = (window as any).google;
      if (!google?.accounts?.oauth2) {
        throw new Error("Google login is not available.");
      }

      await new Promise<void>((resolve, reject) => {
        const tokenClient = google.accounts.oauth2.initTokenClient({
          client_id: config.client_id,
          scope: "openid email profile",
          prompt: "select_account",
          callback: async (response: { access_token?: string; error?: string }) => {
            if (response.error || !response.access_token) {
              reject(new Error(response.error || "Google did not return an access token."));
              return;
            }

            try {
              const nextSession = await loginWithGoogleToken(response.access_token);
              storeSession(nextSession);
              setUser(mapUnapiUser(nextSession.user as UnapiUser & { provider?: AuthProvider }, undefined, "google"));
              await loadRemoteWorkspace(nextSession.auth.access_token);
              setLandingMode("workspace");
              setShowStartChoiceModal(true);
              setMobileMenuOpen(false);
              setApiNotice(lang === "en" ? "Logged in with Google." : "Login Google berhasil.");
              resolve();
            } catch (error) {
              reject(error);
            }
          },
        });

        tokenClient.requestAccessToken();
      });
    } catch (error) {
      setApiError(error, lang === "en" ? "Google login failed." : "Login Google gagal.");
    } finally {
      setAuthBusy(false);
    }
  }

  async function handleEmailLogin(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (!loginEmail.trim()) {
      alert(lang === "en" ? "Please enter your email." : "Silakan isi email.");
      return;
    }
    if (!loginPassword) {
      alert(lang === "en" ? "Please enter your password." : "Silakan isi password.");
      return;
    }

    setAuthBusy(true);
    try {
      const nextSession = await loginToUnapi(loginEmail.trim(), loginPassword);
      storeSession(nextSession);
      const access = await ensurePakposAccess(nextSession.auth.access_token).catch(() => null);
      setUser(mapUnapiUser(nextSession.user, access?.membership?.status));
      await loadRemoteWorkspace(nextSession.auth.access_token);
      setLandingMode("workspace");
      setShowStartChoiceModal(true);
      setMobileMenuOpen(false);
      setApiNotice(lang === "en" ? "Logged in with UNAPI." : "Login UNAPI berhasil.");
    } catch (error) {
      setApiError(error, lang === "en" ? "Login failed." : "Login gagal.");
    } finally {
      setAuthBusy(false);
    }
  }

  async function handleLogout() {
    if (accessToken) {
      await logoutFromUnapi(accessToken).catch(() => null);
    }
    clearSession();
    setLandingMode("landing");
    setStep("import");
    setMobileMenuOpen(false);
    setShowSettingsModal(false);
  }

  async function handleRegisterSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (!registerName.trim() || !registerEmail.trim() || !registerPassword) {
      alert(lang === "en" ? "Please complete the registration form." : "Lengkapi form registrasi.");
      return;
    }
    if (registerPassword !== registerConfirm) {
      alert(lang === "en" ? "Password confirmation does not match." : "Konfirmasi password tidak cocok.");
      return;
    }

    setAuthBusy(true);
    try {
      const nextSession = await registerToUnapi({
        full_name: registerName.trim(),
        name: registerName.trim(),
        email: registerEmail.trim(),
        password: registerPassword,
      });
      storeSession(nextSession);
      await ensurePakposAccess(nextSession.auth.access_token).catch(() => null);
      await loadRemoteWorkspace(nextSession.auth.access_token);
      setShowRegisterModal(false);
      setLandingMode("workspace");
      setShowStartChoiceModal(true);
      setApiNotice(lang === "en" ? "Registration completed through UNAPI." : "Registrasi UNAPI berhasil.");
    } catch (error) {
      setApiError(error, lang === "en" ? "Registration failed." : "Registrasi gagal.");
    } finally {
      setAuthBusy(false);
    }
  }

  async function handleForgotPassword() {
    if (!loginEmail.trim()) {
      alert(lang === "en" ? "Enter your email first." : "Isi email terlebih dahulu.");
      return;
    }

    try {
      await forgotPasswordUnapi(loginEmail.trim());
      alert(
        lang === "en"
          ? "Password reset request sent through UNAPI."
          : "Permintaan reset password dikirim melalui UNAPI."
      );
    } catch (error) {
      setApiError(error, lang === "en" ? "Failed to request reset." : "Gagal meminta reset.");
    }
  }

