  function openSplitConfigFromHistory(item: ImportHistoryItem) {
    setImportedContent(item);
    setSplitMinWords(item.minWords || 80);
    setSplitMaxWords(item.maxWords || 180);
    setSplitImageMode(item.imageMode || "upload");
    setSplitVideoMode(item.videoMode || "none");
    setShowHistoryModal(false);
    setMaxChars(Math.max(100, (item.maxWords || 180) * 6));
    setStep("split");
  }

  function continueFromSplitConfig() {
    if (!splitConfigItem) return;

    if (splitImageMode === "create" || splitVideoMode === "create") {
      alert(
        lang === "en"
          ? "Your account cannot create video or image yet. Please use upload mode for now."
          : "Akun Anda belum bisa membuat video atau gambar. Untuk saat ini gunakan mode upload."
      );
    }

    const nextItem: ImportHistoryItem = {
      ...splitConfigItem,
      minWords: splitMinWords,
      maxWords: splitMaxWords,
      imageMode: splitImageMode,
      videoMode: splitVideoMode,
    };

    setImportedContent(nextItem);

    setImportHistory((prev) =>
      prev.map((item) =>
        item.id === nextItem.id
          ? {
              ...nextItem,
            }
          : item
      )
    );

    setMaxChars(Math.max(100, splitMaxWords * 6));
    setSplitConfigItem(null);
    setStep("split");
  }

