  function getDraftPostCodeLocal(draftId: string) {
    const index = drafts.findIndex((draft) => draft.id === draftId);
    return `post-${String(index + 1).padStart(3, "0")}`;
  }

  function getDraftStatusText(draft: DraftPost) {
    const queueItem = queue.find((item) => item.draftId === draft.id);

    if (queueItem?.status === "published") {
      return lang === "en" ? "Posted" : "Sudah dipost";
    }

    if (queueItem?.status === "publishing") {
      return lang === "en" ? "Posting..." : "Sedang posting...";
    }

    if (queueItem?.status === "scheduled") {
      return lang === "en" ? "Scheduled" : "Terjadwal";
    }

    if (draft.status === "approved" || draft.status === "reviewed") {
      return lang === "en" ? "Saved" : "Tersimpan";
    }

    return "Draft";
  }

  function getDraftPostingTargets(draft: DraftPost) {
    if (!draft.platforms.length) {
      return lang === "en" ? "No platform selected" : "Belum pilih platform";
    }

    return `Posting in ${draft.platforms
      .map((platform) => getPlatform(platform)?.label || platform)
      .join(", ")}`;
  }

