  async function saveReviewDraft(draftId: string) {
    const draft = drafts.find((item) => item.id === draftId);

    if (!draft || !draft.caption.trim()) {
      alert(lang === "en" ? "Caption cannot be empty." : "Caption tidak boleh kosong.");
      return;
    }

    let remoteId = draft.remoteArticleId;
    try {
      remoteId = await persistDraftToUnapi(draft, "reviewed");
      setApiNotice(lang === "en" ? "Draft saved to UNAPI." : "Draft tersimpan ke UNAPI.");
    } catch (error) {
      setApiError(error, lang === "en" ? "Failed to save draft." : "Gagal menyimpan draft.");
      return;
    }

    setDrafts((prev) =>
      prev.map((item) =>
        item.id === draftId
          ? {
              ...item,
              remoteArticleId: remoteId,
              status: "reviewed",
            }
          : item
      )
    );
  }

  function ensureImageAsMediaAsset(draft: DraftPost) {
    if (!draft.image) return;

    const alreadyExists = mediaAssets.some(
      (asset) => asset.postId === draft.id && asset.storedName === draft.image?.name
    );

    if (alreadyExists) return;

    const postCode = getDraftPostCodeLocal(draft.id);

    const asset: MediaAsset = {
      id: makeId("media"),
      postId: draft.id,
      postCode,
      type: "image",
      source: "user",
      originalName: draft.image.name,
      storedName: draft.image.name,
      url: draft.image.url,
      mimeType: "image/*",
      version: 1,
      status: "ready",
      createdAt: new Date().toISOString(),
    };

    setMediaAssets((prev) => [asset, ...prev]);
  }

  async function confirmReviewSchedule(draftId: string) {
    const draft = drafts.find((item) => item.id === draftId);
    const scheduledAt = draftSchedules[draftId];

    if (!draft) return;

    if (!draft.caption.trim()) {
      alert(lang === "en" ? "Please write the caption first." : "Silakan isi caption terlebih dahulu.");
      return;
    }

    if (!draft.image) {
      alert(lang === "en" ? "Please choose an image first." : "Silakan pilih gambar terlebih dahulu.");
      return;
    }

    if (!scheduledAt) {
      alert(lang === "en" ? "Please choose date and time for scheduling." : "Silakan pilih tanggal dan jam schedule.");
      return;
    }

    if (draft.platforms.length === 0) {
      alert(t.platformAlert);
      return;
    }

    if (!accessToken) {
      setLandingMode("login");
      alert(lang === "en" ? "Please log in before scheduling." : "Silakan login sebelum menjadwalkan.");
      return;
    }

    ensureImageAsMediaAsset(draft);

    let remoteArticleId = draft.remoteArticleId;
    let remoteQueueId: string | number | undefined;
    try {
      remoteArticleId = await persistDraftToUnapi(draft, "approved");
      if (remoteArticleId) {
        await submitArticle(accessToken, remoteArticleId).catch(() => null);
        await reviewArticle(accessToken, remoteArticleId, {
          status: "approved",
          decision: "approved",
        }).catch(() => null);
      }

      const scheduleResponse = await scheduleSocialcast(accessToken, {
        app_code: APP_CODE,
        draft_id: draft.id,
        article_id: remoteArticleId,
        caption: draft.caption,
        platforms: draft.platforms,
        scheduled_at: scheduledAt,
        publish_mode: "scheduled",
        media_assets: mediaAssets.filter((asset) => asset.postId === draft.id),
      });
      remoteQueueId = getRemoteId(scheduleResponse);
      setApiNotice(lang === "en" ? "Schedule saved to UNAPI." : "Jadwal tersimpan ke UNAPI.");
    } catch {
      setApiNotice(
        lang === "en"
          ? "UNAPI did not accept the schedule request yet. The schedule is saved locally and can be synced again after the endpoint is ready."
          : "UNAPI belum menerima request jadwal. Jadwal disimpan lokal dan bisa disinkronkan lagi setelah endpoint siap."
      );
    }

    setDrafts((prev) =>
      prev.map((item) =>
        item.id === draftId
          ? {
              ...item,
              remoteArticleId,
              status: "approved",
            }
          : item
      )
    );

    setQueue((prev) => {
      const exists = prev.some((item) => item.draftId === draftId);

      const queueItem: QueueItem = {
        id: makeId("queue"),
        remoteId: remoteQueueId,
        draftId,
        caption: draft.caption,
        platforms: draft.platforms,
        image: draft.image,
        scheduledAt,
        publishMode: "scheduled",
        status: "scheduled",
      };

      if (exists) {
        return prev.map((item) =>
          item.draftId === draftId
            ? {
                ...item,
                remoteId: remoteQueueId || item.remoteId,
                caption: draft.caption,
                platforms: draft.platforms,
                image: draft.image,
                scheduledAt,
                publishMode: "scheduled",
                status: "scheduled",
              }
            : item
        );
      }

      return [queueItem, ...prev];
    });

    setActiveReviewDraftId(null);
    setStep("schedule");
  }
